function balikString(s) {
  let hasil = "";
  for (let i = s.length - 1; i >= 0; i--) hasil += s[i];
  return hasil;
}

solutions.go:
func balikString(s string) string {
	huruf := []rune(s)
	for i, j := 0, len(huruf)-1; i < j; i, j = i+1, j-1 {
		huruf[i], huruf[j] = huruf[j], huruf[i]
	}
	return string(huruf)
}
